return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'so_SO','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-03T18:22:39+00:00','po-revision-date'=>'2026-09-03T18:22:39+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'Kaydinta iyo mashiinka wanaajinta dhammaystiran ee WordPress: kaydinta bogga buuxa, kaydinta shayga, nadiifinta xog-ururinta iyo wanaajinta CSS/JS. Ku rakib tan marka martigeliyahaagu uusan bixin lakabka kaydinta ee uu leeyahay — martigelinta Zinn Digital® halkaas ku rakib Zinn® Cache beddelkeeda. Kaydinta bogga buuxa waxay u baahan tahay server LiteSpeed ​​ama OpenLiteSpeed ​​oo leh qaybta LSCache. Fargeetada GPLv3 ee LiteSpeed Cache plugin.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d saacadood','%d hour'=>'%d saacad','%d minutes'=>'%d daqiiqadood','%d minute'=>'%d daqiiqad','Purged All!'=>'Dhammaan waa la nadiifiyey!','Purged the blog!'=>'Blog-ga waa la nadiifiyey!','Purged the URL!'=>'URL-kii waa la sifeeyay!','Purged!'=>'La tirtiray!','Failed to upgrade.'=>'Waa lagu guuldarraystay in la cusboonaysiiyo.','Upgraded successfully.'=>'Si guul leh ayaa loo casriyeeyay.','Dashboard'=>'Golaha Hagidda','OptimaX'=>'OptimaX','Presets'=>'Hordhacyada','General'=>'Guud ahaan','Cache'=>'Kaydka xogta ku meel-gaarka ah','CDN'=>'CDN','Image Opti